// @generated by:gauntlet run:godseye-local-recovery
import { randomUUID } from "node:crypto";
import { InfrastructureEngine } from "@godseye/core";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { recoveryCommitments } from "../packages/core/src/recovery-capacity.js";
import { type RecoveryFixture, recoveryFixture } from "./recovery-helpers.js";

describe("authenticated continuous archive interval refresh", () => {
  let fixture: RecoveryFixture;
  beforeEach(async () => {
    fixture = await recoveryFixture();
  });
  afterEach(async () => {
    await fixture.store.close();
  });
  async function input(backupId: string) {
    const project = await fixture.core.getProject(fixture.freshOwner(), fixture.project.id);
    const environment = project.environments.find((item) => item.id === fixture.development.id);
    if (!environment) throw new Error("Archive fixture source missing");
    return {
      projectId: project.id,
      sourceEnvironmentId: environment.id,
      backupId,
      expectedProjectRevision: project.revision,
      expectedEnvironmentRevision: environment.revision,
    };
  }
  async function prepare(backupId: string, key = randomUUID()) {
    return fixture.infrastructure.recovery.prepareArchiveCheck(
      fixture.freshOwner(),
      await input(backupId),
      key,
    );
  }
  const storage = async () =>
    (await recoveryCommitments(fixture.store.db)).reduce((sum, item) => sum + item.storageGiB, 0);

  it("T-AC-35 T-AC-36 extends the exact existing backup interval so later archived data can be selected", async () => {
    const { backup } = await fixture.backup(),
      original = structuredClone(
        fixture.recoveryProvider.resources.values().next().value?.metadata,
      );
    fixture.clock.advance(120_000);
    const target = fixture.clock.now().toISOString();
    await expect(fixture.prepareRestore(backup.id, "too-early", target)).rejects.toMatchObject({
      code: "ARCHIVE_UNAVAILABLE",
    });
    const preparation = await prepare(backup.id),
      run = await fixture.admitRecovery(preparation);
    await fixture.infrastructure.foundation.tick("archive-refresh-worker");
    const overview = await fixture.infrastructure.recovery.overview(fixture.freshOwner());
    expect(overview.backups).toHaveLength(1);
    expect(overview.backups[0]).toMatchObject({
      id: backup.id,
      archiveCheckedAt: target,
      recoverableTo: target,
    });
    expect(overview.runs.find((item) => item.id === run.id)?.state).toBe("archive-checked");
    const effect = fixture.recoveryProvider.effects.find((item) => item.action === "check");
    expect(effect?.scope.backup?.manifestHash).toBe(original?.manifestHash);
    expect((await fixture.prepareRestore(backup.id, "later-archive", target)).targetTime).toBe(
      target,
    );
  });

  it("T-AC-38 replays and concurrently consumes one check without multiplying repository reservations", async () => {
    const { backup } = await fixture.backup(),
      baseline = await storage(),
      key = randomUUID();
    const preparation = await prepare(backup.id, key);
    expect(await prepare(backup.id, key)).toEqual(preparation);
    const admitKey = randomUUID();
    const [a, b] = await Promise.all([
      fixture.admitRecovery(preparation, admitKey),
      fixture.admitRecovery(preparation, admitKey),
    ]);
    expect(a.id).toBe(b.id);
    expect(await storage()).toBe(baseline + preparation.policy.stagingGiB);
    await Promise.all([
      fixture.infrastructure.foundation.tick("archive-worker-a"),
      fixture.infrastructure.foundation.tick("archive-worker-b"),
    ]);
    expect(fixture.recoveryProvider.effects.filter((item) => item.action === "check")).toHaveLength(
      1,
    );
    expect(await storage()).toBe(baseline);
    const next = await prepare(backup.id);
    await fixture.admitRecovery(next);
    await fixture.infrastructure.foundation.tick("second-archive-worker");
    expect(await storage()).toBe(baseline);
    expect(
      (await fixture.infrastructure.recovery.overview(fixture.freshOwner())).backups,
    ).toHaveLength(1);
  });

  it("T-AC-41 reconciles a lost check receipt after reconstruction without checking or backing up twice", async () => {
    const { backup } = await fixture.backup();
    fixture.clock.advance(30_000);
    const preparation = await prepare(backup.id),
      run = await fixture.admitRecovery(preparation);
    fixture.recoveryProvider.lostAcknowledgments.add("check");
    await fixture.infrastructure.foundation.tick("lost-archive-check-worker");
    const effects = structuredClone(fixture.recoveryProvider.effects),
      commitments = await storage();
    const restarted = new InfrastructureEngine(fixture.store, fixture.configuration);
    await restarted.foundation.reconcile(fixture.freshOwner(), run.runId, randomUUID());
    expect(
      (await restarted.recovery.overview(fixture.freshOwner())).runs.find(
        (item) => item.id === run.id,
      )?.state,
    ).toBe("archive-checked");
    expect(fixture.recoveryProvider.effects).toEqual(effects);
    expect(await storage()).toBeLessThan(commitments);
  });

  it("T-AC-38 denies foreign backup scope and stale source epochs before any archive check", async () => {
    const { backup } = await fixture.backup();
    await expect(
      fixture.infrastructure.recovery.prepareArchiveCheck(
        fixture.freshOwner(),
        { ...(await input(backup.id)), sourceEnvironmentId: fixture.production.id },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ code: "FORBIDDEN" });
    const preparation = await prepare(backup.id),
      run = await fixture.admitRecovery(preparation);
    await fixture.infrastructure.foundation.advanceEpoch(
      fixture.freshOwner(),
      fixture.development.id,
      randomUUID(),
    );
    await fixture.infrastructure.foundation.tick("stale-check-epoch-worker");
    expect(fixture.recoveryProvider.effects.filter((item) => item.action === "check")).toEqual([]);
    expect(
      (await fixture.infrastructure.recovery.overview(fixture.freshOwner())).runs.find(
        (item) => item.id === run.id,
      )?.state,
    ).not.toBe("archive-checked");
  });

  it("T-AC-41 retains unknown check staging until independent evidence proves its exact outcome", async () => {
    const { backup } = await fixture.backup(),
      baseline = await storage(),
      preparation = await prepare(backup.id),
      run = await fixture.admitRecovery(preparation);
    fixture.recoveryProvider.beforeAction = async (action) => {
      if (action === "check") throw new Error("Archive-check receipt unavailable");
    };
    await fixture.infrastructure.foundation.tick("unavailable-archive-check-worker");
    fixture.recoveryProvider.beforeAction = undefined;
    await fixture.infrastructure.foundation.reconcile(
      fixture.freshOwner(),
      run.runId,
      randomUUID(),
    );
    expect(
      (await fixture.infrastructure.recovery.overview(fixture.freshOwner())).runs.find(
        (item) => item.id === run.id,
      )?.state,
    ).toBe("unknown");
    expect(await storage()).toBe(baseline + preparation.policy.stagingGiB);
    expect(await fixture.infrastructure.foundation.tick("never-repeat-unknown-check-worker")).toBe(
      false,
    );
    expect(fixture.recoveryProvider.effects.filter((item) => item.action === "check")).toEqual([]);
  });

  it.each(["manifest", "timeline", "source", "interval-rewind"])(
    "T-AC-36 rejects archive refresh with %s drift without replacing authenticated backup coverage",
    async (mode) => {
      const { backup } = await fixture.backup(),
        preparation = await prepare(backup.id),
        run = await fixture.admitRecovery(preparation);
      fixture.recoveryProvider.inspectionResult = (result) => {
        if (mode === "manifest") result.metadata.manifestHash = "f".repeat(64);
        if (mode === "timeline") result.metadata.timeline += 1;
        if (mode === "source") result.metadata.sourceAllocationId = randomUUID();
        if (mode === "interval-rewind") result.metadata.recoverableTo = "2026-11-11T11:02:00.000Z";
        return result;
      };
      await fixture.infrastructure.foundation.tick("archive-drift-worker");
      const overview = await fixture.infrastructure.recovery.overview(fixture.freshOwner());
      expect(overview.runs.find((item) => item.id === run.id)?.state).toBe("unknown");
      expect(overview.backups[0]?.recoverableTo).toBe(backup.recoverableTo);
      expect(overview.backups).toHaveLength(1);
    },
  );
});
